#include <bits/stdc++.h>
using namespace std;

// floor(sqrt(x)) dla 0 <= x <= LLONG_MAX, zawsze poprawne
long long isqrt(long long x) {
    long long r = (long long)sqrtl((long double)x);
    while (r > 0 && r > x / r) r--;            // r*r > x
    while (r + 1 <= x / (r + 1)) r++;          // (r+1)^2 <= x
    return r;
}

// floor(cbrt(x)) dla x >= 0
long long icbrt(long long x) {
    long long r = (long long)cbrtl((long double)x);
    while (r > 0 && (__int128)r * r * r > x) r--;
    while ((__int128)(r + 1) * (r + 1) * (r + 1) <= x) r++;
    return r;
}

// a^b bez modulo (uważaj na przepełnienie!)
long long ipow(long long a, int b) {
    long long r = 1;
    while (b--) r *= a;
    return r;
}

int main() {
    long long x = 999999999999999999LL;
    cout << (long long)sqrt(x) << ' ' << isqrt(x) << '\n';   // 1000000000 999999999
    cout << icbrt(1000000000000000000LL) << '\n';            // 1000000
    cout << ipow(5, 25) << ' ' << (long long)pow(5, 25) << '\n';
}

